      syslog(LOG_ERR, "%s: draw buffer init failed\n",
             LVGL_APP_FBDEV_COMPAT_TAG);
      goto errout;
    }

  disp = lv_display_create(fb->vinfo.xres, fb->vinfo.yres);
  if (disp == NULL)
    {
      goto errout;
    }

