static void pwm_action_set(u32 ch, struct aic_pwm_action *act, char *name) {
  u32 offset;
  u32 action = g_pwm_args[ch].def_level ? PWM_AQCTL_DEF_LEVEL : 0;

  if (strcmp(name, "action0") == 0)
    offset = PWM_AQCTLA(ch);
