  action |=
      (act->CBD << PWM_AQCTL_CBD_SHIFT) | (act->CBU << PWM_AQCTL_CBU_SHIFT) |
      (act->CAD << PWM_AQCTL_CAD_SHIFT) | (act->CAU << PWM_AQCTL_CAU_SHIFT) |
      (act->PRD << PWM_AQCTL_PRD_SHIFT) | act->ZRO;
  pwm_writel(action, offset);
}

